import{_ as e,o as a,c as r,aA as o}from"./chunks/framework.BMzE2Z9R.js";const h=JSON.parse('{"title":"通用人工智能","description":"","frontmatter":{"comments":true},"headers":[],"relativePath":"agi/index.md","filePath":"agi/index.md","lastUpdated":1778399398000}'),n={name:"agi/index.md"};function l(s,t,i,d,c,p){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="通用人工智能" tabindex="-1">通用人工智能 <a class="header-anchor" href="#通用人工智能" aria-label="Permalink to &quot;通用人工智能&quot;">​</a></h1><p>这个词汇里包含了 <strong>通用</strong> 二字, 代表比肩人类的<strong>多能力的有机统一</strong> .</p><p>英文是 Artificial General Intelligence, 或简称AGI。</p><table tabindex="0"><thead><tr><th>比较</th><th>AGI</th><th>AI</th></tr></thead><tbody><tr><td>英文</td><td>Artificial General Intelligence</td><td>Artificial Intelligence</td></tr><tr><td>含义</td><td>强人工智能，或超级人工智能，拥有自我意识，能听懂人话，能像人一样思考和推理的智能，适用于所有行业</td><td>弱人工智能，大数据，深度学习，机器学习，人脸识别，自动驾驶，语音识别，机器翻译，推荐系统</td></tr></tbody></table><p>从历史上看, <strong>AGI</strong> 的本意就是 <strong>AI</strong> 的初心, 但后来 AI 这个词逐渐被 智能电饭锅/智能手机/智能人脸识别 等 <strong>窄应用</strong> 霸占了, 然后大家一商量, 就决定换一个词, 这个词继续承接 <strong>终极思维机器</strong> 的理想前行。</p><p>AGI (通用人工智能) 的发展史, 以及各种相关项目列表, 请参考这篇文章:</p><p><a href="https://www.jiqizhixin.com/articles/2018-11-15-6" target="_blank" rel="noreferrer">通用人工智能导航：AGI的历史与现状</a>。</p><p>AGI研究追求<strong>创造出具有类人智能的机器的目标</strong>，尽管“类人”可以以<strong>不同的抽象层次</strong>来解释（Goertzel和Pennachin，2007; Wang和Goertzel，2007）。对我们来说，<strong>这意味着一台机器可以像人类一样记忆、学习、规划、推理和追求目标</strong>，换句话说，<strong>将智能视为一种高度抽象和普遍的能力</strong>（Wang，2019）。</p><details class="callout" data-callout="note" data-callout-fold="-"><summary class="callout-title"><div class="callout-title-icon"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-pencil"><path d="M17 3a2.85 2.83 0 1 1 4 4L7.5 20.5 2 22l1.5-5.5Z"></path><path d="m15 5 4 4"></path></svg></div><div class="callout-title-inner">王培教授对AGI这个领域感兴趣者，特别是年轻人的建议：</div><div class="callout-fold"></div></summary><div class="callout-content"><p></p><p><strong>多看文献，多看各方面的（进展），不要轻易相信任何人，包括我在内。</strong></p><blockquote><p><a href="https://www.bilibili.com/video/BV1fS4y177JZ/?p=4&amp;share_source=copy_web&amp;vd_source=69a514dc0e2aaf825077e413b7f6a4d4&amp;t=2990" target="_blank" rel="noreferrer">【2022年第七届中国通用人工智能年会_主旨报告】 【精准空降到 49:50】</a></p></blockquote></div></details>',9)])])}const u=e(n,[["render",l]]);export{h as __pageData,u as default};
